  margin-bottom: 20px;
}

.feature-card h3 {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 12px;
}

.feature-card p {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.65;
}

/* --- Page Header (non-home) --- */
.page-hero {
  padding: 80px 0 60px;
  background: var(--bg-primary);
}

.page-hero .heading-lg {
  margin-bottom: 16px;
}

.page-hero .body-lg {
  max-width: 560px;
}

/* --- Animations --- */
@keyframes fadeSlideIn {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.animate-in {
  animation: fadeSlideIn 0.6s ease both;
}

.stagger-1 { animation-delay: 0.1s; }
.stagger-2 { animation-delay: 0.2s; }
.stagger-3 { animation-delay: 0.3s; }
.stagger-4 { animation-delay: 0.4s; }

/* --- Mobile Menu --- */
@media (max-width: 1024px) {
  .primary-nav {
    position: fixed;
    top: 0;
    right: -100%;
    width: 320px;
    height: 100vh;
    background: var(--bg-surface);
    flex-direction: column;
    padding: 120px 40px 40px;
    gap: 24px;
    transition: right 0.4s cubic-bezier(0.25, 0.1, 0.25, 1);
    border-left: 1px solid var(--border);
    z-index: 1001;
  }

  .primary-nav.open {
    right: 0;
  }

  .menu-toggle {
    display: flex;
  }

  .mobile-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.6);
    z-index: 1000;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s;
  }

  .mobile-overlay.open {
    opacity: 1;
    pointer-events: auto;
  }
}

/* --- Responsive --- */
@media (max-width: 768px) {
  :root {
    --header-height: 64px;
  }

  .promo-bar {
    font-size: 11px;
    padding: 8px 16px;
  }

  .site-header {
    top: 34px;
  }

  .section {
    padding: 60px 0;
  }

  .community-grid,
  .studio-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .way-card {
    padding: 36px 28px;
  }

  .hero {
    min-height: auto;
    padding: 60px 0;
  }

  .hero-visual {
    display: none;
  }

  .hero-title {
    font-size: 36px;
  }

  .hero-ctas {
    flex-direction: column;
  }

  .hero-ctas .btn {
    width: 100%;
    text-align: center;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 32px;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .carousel-arrow {
    width: 40px;
    height: 40px;
  }

  .filter-bar {
    gap: 8px;
  }

  .filter-chip {
    padding: 8px 14px;
    font-size: 11px;
  }

  .instructor-grid {
    grid-template-columns: 1fr 1fr;
    gap: 16px;
  }

  .features-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .toggle-btn {
    padding: 14px 24px;
    font-size: 13px;
  }

  .schedule-table th,
  .schedule-table td {
    padding: 12px 16px;
  }
}

@media (max-width: 480px) {
  .heading-xl {
    font-size: 32px;
  }

  .heading-lg {
    font-size: 28px;
  }

  .heading-md {
    font-size: 22px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }

  .instructor-grid {
    grid-template-columns: 1fr;
  }

  .btn-lg {
    padding: 16px 32px;
    font-size: 15px;
  }

  .site-header {
    top: 32px;
  }

  .logo {
    font-size: 20px;
  }
}

